.ds-view-board { font-family:var(--font-sans, 'Hanken Grotesk', sans-serif); font-weight:400; line-height:1.6; color:var(--color-ink, #26332E); } .ds-view-board figure, .ds-view-board p { margin:0; } .ds-view-board a { color:inherit; text-decoration:none; } .ds-view-board a:focus-visible, .ds-view-board button:focus-visible { outline:2px solid var(--color-accent, #345E50); outline-offset:5px; } .ds-view-reader { box-sizing:border-box; } .ds-gallery-count { white-space:nowrap; font-variant-numeric:tabular-nums; font-size:16px; } .ds-text-control { display:inline-flex; align-items:center; gap:12px; min-height:44px; padding:6px 0; border:0; background:transparent; font:inherit; font-size:16px; color:inherit; cursor:pointer; } .ds-view-board { scroll-margin-top: calc(var(--header-height, 74px) + 65px); }
.ds-board-toolbar { display: flex; flex-direction: column; gap: 14px; margin-bottom: 22px; }
.ds-board-toolbar > p { font-size: 15px; color: var(--color-muted, #5C6B62); }
.ds-board-rooms { display: flex; flex-wrap: wrap; gap: 4px 20px; }
.ds-board-rooms button { display: inline-flex; gap: 7px; align-items: center; min-height: 44px; padding: 6px 0; border: 0; background: transparent; font-size: 15px; }
.ds-board-rooms button span { font-size: 12px; color: var(--color-muted, #5C6B62); font-variant-numeric: tabular-nums; }
.ds-board-rooms button[aria-pressed="true"] { color: var(--color-accent, #345E50); text-decoration: underline; text-underline-offset: 6px; }
.ds-board-grid { display: flex; flex-wrap: wrap; gap: 22px; align-items: flex-start; }
.ds-board-item { flex: 1 1 calc((100% - 44px) / 3); min-width: 0; }
.ds-board-grid[data-count="2"] .ds-board-item, .ds-board-grid[data-count="4"] .ds-board-item { flex-basis: calc((100% - 22px) / 2); }
.ds-board-grid[data-count="5"] .ds-board-item:nth-child(-n+2) { flex-basis: calc((100% - 22px) / 2); }
.ds-board-grid[data-count="7"] .ds-board-item:nth-child(n+4), .ds-board-grid[data-count="8"] .ds-board-item { flex-basis: calc((100% - 66px) / 4); }
.ds-board-visual { display: block; position: relative; overflow: hidden; background: var(--project-surface); scroll-margin-top: calc(var(--header-height, 74px) + 80px); }
.ds-board-visual img { width: 100%; height: auto; clip-path: inset(0); transition: clip-path .35s cubic-bezier(.16,1,.3,1); }
.ds-board-open { position: absolute; inset: auto 0 0; display: flex; align-items: center; justify-content: space-between; height: 34px; padding-inline: 12px; font-size: 14px; background: var(--project-surface); transform: translateY(100%); transition: transform .35s cubic-bezier(.16,1,.3,1); pointer-events: none; }
.ds-board-visual:hover img, .ds-board-visual:focus-visible img { clip-path: inset(0 0 34px 0); }
.ds-board-visual:hover .ds-board-open, .ds-board-visual:focus-visible .ds-board-open { transform: translateY(0); }
.ds-board-item[data-active="true"] .ds-board-visual { outline: 2px solid var(--color-accent, #345E50); outline-offset: -2px; }
.ds-board-item figcaption { padding-top: 12px; font-size: 15px; line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; hyphens: auto; }
.ds-view-reader { width: min(1400px, calc(100vw - 40px)); max-width: calc(100vw - 40px); height: calc(100dvh - 40px); max-height: calc(100dvh - 40px); padding: 0 28px 28px; border: 0; margin: auto; background: var(--color-canvas, #F3F5F2); color: var(--color-ink, #26332E); overflow-y: auto; overscroll-behavior: contain; touch-action: pan-y; }
.ds-view-reader::backdrop { background: #26332EEB; }
.ds-reader-top { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding-block: 18px; background: var(--color-canvas, #F3F5F2); border-bottom: 1px solid var(--color-rule, #CDD6CE); }
.ds-reader-top > div { min-width: 0; }
.ds-reader-top p { font-size: 17px; overflow-wrap: anywhere; hyphens: auto; }
.ds-reader-top > div > span { font-size: 13px; color: var(--color-muted, #5C6B62); }
.ds-reader-top .ds-text-control { flex-shrink: 0; }
.ds-reader-view { padding-block: 24px; scroll-margin-top: var(--reader-header-height, 100px); }
.ds-reader-view img { width: 100%; height: auto; max-height: 74dvh; object-fit: contain; background: var(--project-surface); }
.ds-reader-view figcaption { display: flex; gap: 30px; justify-content: space-between; padding-block: 15px 24px; border-bottom: 1px solid var(--color-rule, #CDD6CE); }
.ds-reader-view figcaption p { max-width: 65ch; font-size: 17px; }
.ds-reader-view figcaption > span { color: var(--color-muted, #5C6B62); font-size: 13px; flex-shrink: 0; }
@media (max-width: 900px) { .ds-view-board .ds-board-grid[data-count] .ds-board-item { flex-basis: calc((100% - 22px) / 2); } }
@media (max-width: 700px) {
  .ds-board-grid { gap: 18px 14px; }
  .ds-view-board .ds-board-grid[data-count] .ds-board-item { flex-basis: calc((100% - 14px) / 2); }
  .ds-board-item figcaption { font-size: 14px; padding-top: 9px; }
  .ds-board-rooms { gap: 3px 16px; }
  .ds-board-rooms button { font-size: 14px; }
  .ds-view-reader { width: calc(100vw - 16px); max-width: calc(100vw - 16px); height: calc(100dvh - 16px); max-height: calc(100dvh - 16px); padding-inline: 14px; }
  .ds-reader-top { display: grid; grid-template-columns: 1fr auto; gap: 8px 14px; padding-block: 12px; }
  .ds-reader-top > div { grid-column: 1 / -1; }
  .ds-reader-top p { font-size: 15px; }
  .ds-reader-top > div > span { font-size: 12px; }
  .ds-reader-top button { justify-self: end; font-size: 14px; }
  .ds-reader-view { padding-block: 18px; }
  .ds-reader-view img { max-height: 65dvh; }
  .ds-reader-view figcaption { flex-direction: column; gap: 9px; padding-block: 12px 18px; }
  .ds-reader-view figcaption p { font-size: 15px; }
}
@media (hover: none) { .ds-board-open { inset: auto 7px 7px auto; width: 28px; height: 28px; padding: 4px; font-size: 0; transform: none; } }
@media (prefers-reduced-motion: reduce) { .ds-board-visual img, .ds-board-open { transition: none; } }

.ds-board-grid { justify-content: center; }
.ds-board-grid[data-count="10"] .ds-board-item:nth-last-child(-n+4), .ds-board-grid[data-count="13"] .ds-board-item:nth-last-child(-n+4) { flex-basis: calc((100% - 66px) / 4); }
.ds-board-grid[data-count="11"] .ds-board-item:nth-last-child(-n+2), .ds-board-grid[data-count="14"] .ds-board-item:nth-last-child(-n+2) { flex-basis: calc((100% - 22px) / 2); }
.ds-reader-view > img { margin-inline: auto; }

@media (max-width:900px) { .ds-view-board .ds-board-grid[data-count] .ds-board-item { flex-basis:calc((100% - 22px)/2); } } @media (max-width:700px) { .ds-view-board .ds-board-grid[data-count] .ds-board-item { flex-basis:calc((100% - 14px)/2); } } .ds-board-rooms button { font-family:var(--font-sans, 'Hanken Grotesk', sans-serif); font-weight:400; line-height:1.6; cursor:pointer; }

.ds-reader-view { font-family:var(--font-sans, 'Hanken Grotesk', sans-serif); font-weight:400; line-height:1.6; color:var(--color-ink, #26332E); } .ds-panorama-preview { display:block; } .ds-panorama-actions, .ds-panorama-buttons > button { box-sizing:border-box; } .ds-panorama-actions button:focus-visible { outline:2px solid var(--color-accent, #345E50); outline-offset:5px; } .ds-text-control { display:inline-flex; align-items:center; min-height:44px; padding:6px 0; border:0; background:transparent; font:inherit; font-size:14px; color:inherit; cursor:pointer; } .ds-panorama-view { position: relative; height: clamp(280px, 62dvh, 650px); background: var(--project-surface); }
.ds-reader-view .ds-panorama-preview { width: 100%; height: 100%; max-height: none; object-fit: contain; }
.ds-panorama-stage { position: absolute; inset: 0; }
.ds-panorama-actions { position: absolute; inset: auto 0 0; z-index: 3; display: flex; justify-content: space-between; align-items: center; gap: 20px; padding: 8px 15px; background: var(--color-canvas, #F3F5F2); border-top: 1px solid var(--color-rule, #CDD6CE); font-size: 14px; }
.ds-panorama-actions > span { max-width: 48ch; }
.ds-panorama-actions button { font-size: 14px; }
.ds-panorama-error { position: absolute; inset: 20px 20px auto; padding: 12px; background: var(--color-canvas, #F3F5F2); font-size: 15px; }



@media (max-width: 700px) {    .ds-panorama-actions { flex-direction: column; align-items: start; gap: 2px; } }

.ds-panorama-buttons { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.ds-panorama-buttons > button:not(.ds-text-control) { display: flex; justify-content: center; align-items: center; width: 44px; height: 44px; background: transparent; border: 1px solid #88988C; }
